quizDraft.solutionCode:
const syncPromise = Promise.reject(new Error("Offline"));
const status = document.querySelector("#sync-status");

async function showSyncResult() {
  try {
    await syncPromise;
    status.textContent = "Sync complete";
  } catch (error) {
    status.textContent = "Sync failed";
  }
}

showSyncResult();

